Value.Calculation:
If ( IsEmpty ( $search ) ;
	"" ;
	" AND (LOWER(Manufacturer) LIKE '%" & $term & "%' OR LOWER(Model) LIKE '%" & $term & "%' OR LOWER(VIN) LIKE '%" & $term & "%' OR LOWER(PlateNumber) LIKE '%" & $term & "%')"
)

JSONSetElement ( "{}" ;
	[ "table" ; "Vehicles" ; JSONString ] ;
	[ "fields" ; JSONSetElement ( "[]" ;
		[ 0 ; "PrimaryKey" ; JSONString ] ;
		[ 1 ; "Manufacturer" ; JSONString ] ;
		[ 2 ; "Model" ; JSONString ] ;
		[ 3 ; "YearManufactured" ; JSONString ] ;
		[ 4 ; "VIN" ; JSONString ] ;
		[ 5 ; "PlateNumber" ; JSONString ] ;
		[ 6 ; "ForeignKeyClient" ; JSONString ]
	) ; JSONArray ] ;
	[ "fieldTypes" ; JSONSetElement ( "[]" ;
		[ 0 ; "string" ; JSONString ] ;
		[ 1 ; "string" ; JSONString ] ;
		[ 2 ; "string" ; JSONString ] ;
		[ 3 ; "number" ; JSONString ] ;
		[ 4 ; "string" ; JSONString ] ;
		[ 5 ; "string" ; JSONString ] ;
		[ 6 ; "string" ; JSONString ]
	) ; JSONArray ] ;
	[ "searchFields" ; JSONSetElement ( "[]" ;
		[ 0 ; "Manufacturer" ; JSONString ] ;
		[ 1 ; "Model" ; JSONString ] ;
		[ 2 ; "VIN" ; JSONString ] ;
		[ 3 ; "PlateNumber" ; JSONString ]
	) ; JSONArray ] ;
	[ "orderBy" ; $orderBy ; JSONString ] ;
	[ "customWhere" ; $customWhere ; JSONString ] ;
	[ "webViewerObject" ; "clientvehiclepicker" ; JSONString ] ;
	[ "callbackFunction" ; "receiveVehicleData" ; JSONString ] ;
	[ "responseKey" ; "vehicles" ; JSONString ] ;
	[ "offset" ; $offset ; JSONNumber ] ;
	[ "limit" ; $limit ; JSONNumber ] ;
	[ "search" ; $search ; JSONString ]
)
